-- Youth convention workers and participants.
-- Categories (workers, participants) and team subcategories (Choir, Ushers, ...)
-- are stored on each member and can be selected when sending announcements or meetings.

alter table public.church_members
  add column if not exists registration_categories text[] not null default '{}',
  add column if not exists audience_teams text[] not null default '{}',
  add column if not exists worker_code text not null default '',
  add column if not exists participant_code text not null default '',
  add column if not exists worker_position text not null default '',
  add column if not exists availability text not null default '',
  add column if not exists meeting_sept_4 text not null default '',
  add column if not exists meeting_sept_5 text not null default '',
  add column if not exists absence_reason text not null default '',
  add column if not exists convention_group text not null default '',
  add column if not exists age_range text not null default '',
  add column if not exists whatsapp text not null default '',
  add column if not exists attended_before text not null default '',
  add column if not exists expectations text not null default '',
  add column if not exists medical_need text not null default '',
  add column if not exists convention_submitted_at timestamptz;

create index if not exists church_members_worker_code_idx
  on public.church_members (worker_code)
  where worker_code <> '';

create index if not exists church_members_participant_code_idx
  on public.church_members (participant_code)
  where participant_code <> '';

create index if not exists church_members_categories_idx
  on public.church_members using gin (registration_categories);

create index if not exists church_members_teams_idx
  on public.church_members using gin (audience_teams);

create or replace function public._json_text_array(p_value jsonb)
returns text[]
language sql
immutable
as $$
  select coalesce((
    select array_agg(trim(x))
    from jsonb_array_elements_text(
      case when jsonb_typeof(p_value) = 'array' then p_value else '[]'::jsonb end
    ) t(x)
    where nullif(trim(x), '') is not null
  ), '{}'::text[]);
$$;

revoke all on function public._json_text_array(jsonb) from public, anon, authenticated;

create or replace function public._notification_recipients(p_filters jsonb)
returns table (
  recipient_type text,
  recipient_id uuid,
  full_name text,
  email text,
  phone text
)
language plpgsql
stable
set search_path = public
as $$
declare
  v_source text := coalesce(nullif(trim(p_filters->>'source'), ''), 'members');
  v_program_id uuid := nullif(p_filters->>'program_id', '')::uuid;
  v_role_ids uuid[] := '{}';
  v_branch_ids uuid[] := '{}';
  v_statuses text[] := '{}';
  v_role_names text[] := '{}';
  v_branch_regions text[] := '{}';
  v_ministry text := nullif(trim(p_filters->>'ministry'), '');
  v_categories text[] := '{}';
  v_teams text[] := '{}';
begin
  if p_filters ? 'role_ids' and jsonb_typeof(p_filters->'role_ids') = 'array' then
    select coalesce(array_agg(x::uuid), '{}')
    into v_role_ids
    from jsonb_array_elements_text(p_filters->'role_ids') t(x)
    where nullif(x, '') is not null;
  end if;

  if p_filters ? 'branch_ids' and jsonb_typeof(p_filters->'branch_ids') = 'array' then
    select coalesce(array_agg(x::uuid), '{}')
    into v_branch_ids
    from jsonb_array_elements_text(p_filters->'branch_ids') t(x)
    where nullif(x, '') is not null;
  end if;

  if p_filters ? 'statuses' and jsonb_typeof(p_filters->'statuses') = 'array' then
    select coalesce(array_agg(x), '{}')
    into v_statuses
    from jsonb_array_elements_text(p_filters->'statuses') t(x)
    where nullif(x, '') is not null;
  end if;

  if p_filters ? 'role_names' and jsonb_typeof(p_filters->'role_names') = 'array' then
    select coalesce(array_agg(x), '{}')
    into v_role_names
    from jsonb_array_elements_text(p_filters->'role_names') t(x)
    where nullif(x, '') is not null;
  end if;

  if p_filters ? 'registration_categories' and jsonb_typeof(p_filters->'registration_categories') = 'array' then
    select coalesce(array_agg(trim(x)), '{}')
    into v_categories
    from jsonb_array_elements_text(p_filters->'registration_categories') t(x)
    where nullif(trim(x), '') is not null;
  end if;

  if p_filters ? 'teams' and jsonb_typeof(p_filters->'teams') = 'array' then
    select coalesce(array_agg(trim(x)), '{}')
    into v_teams
    from jsonb_array_elements_text(p_filters->'teams') t(x)
    where nullif(trim(x), '') is not null;
  end if;

  if p_filters ? 'branch_regions' and jsonb_typeof(p_filters->'branch_regions') = 'array' then
    select coalesce(array_agg(x), '{}')
    into v_branch_regions
    from jsonb_array_elements_text(p_filters->'branch_regions') t(x)
    where nullif(x, '') is not null;
  end if;

  if v_source = 'program_registrants' or v_program_id is not null then
    return query
    select
      'registration'::text,
      pr.id,
      pr.full_name,
      pr.email,
      pr.phone
    from public.program_registrations pr
    left join public.church_branches b on b.id = pr.branch_id
    where pr.status in ('registered', 'confirmed', 'attended')
      and (v_program_id is null or pr.program_id = v_program_id)
      and (cardinality(v_branch_ids) = 0 or pr.branch_id = any(v_branch_ids))
      and (cardinality(v_branch_regions) = 0 or coalesce(b.region, '') = any(v_branch_regions));
    return;
  end if;

  return query
  select
    'member'::text,
    m.id,
    m.full_name,
    m.email,
    m.phone
  from public.church_members m
  left join public.church_branches b on b.id = m.branch_id
  where m.status is distinct from 'inactive'
    and (
      cardinality(v_statuses) = 0
      or m.status = any(v_statuses)
    )
    and (
      cardinality(v_role_ids) = 0
      or exists (
        select 1 from public.church_member_roles mr
        where mr.member_id = m.id and mr.role_id = any(v_role_ids)
      )
      or m.role_id = any(v_role_ids)
    )
    and (cardinality(v_branch_ids) = 0 or m.branch_id = any(v_branch_ids))
    and (
      cardinality(v_role_names) = 0
      or exists (
        select 1
        from public.church_member_roles mr
        join public.church_roles cr on cr.id = mr.role_id
        where mr.member_id = m.id and cr.name = any(v_role_names)
      )
    )
    and (cardinality(v_branch_regions) = 0 or coalesce(b.region, '') = any(v_branch_regions))
    and (v_ministry is null or m.ministry ilike '%' || v_ministry || '%')
    and (
      cardinality(v_categories) = 0
      or coalesce(m.registration_categories, '{}') && v_categories
    )
    and (
      cardinality(v_teams) = 0
      or coalesce(m.audience_teams, '{}') && v_teams
      or exists (
        select 1
        from unnest(string_to_array(coalesce(m.ministry, ''), ',')) part
        where trim(part) <> '' and trim(part) = any(v_teams)
      )
    );
end;
$$;


create or replace function public.admin_list_church_members(
  p_token text,
  p_role_id uuid default null,
  p_branch_id uuid default null,
  p_status_group text default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  perform public._require_permission(p_token, 'church_members', 'view');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', m.id,
      'name_title', m.name_title, 'first_name', m.first_name, 'last_name', m.last_name,
      'full_name', m.full_name, 'email', m.email, 'phone', m.phone,
      'gender', m.gender, 'date_of_birth', m.date_of_birth,
      'address', m.address, 'city', m.city, 'state', m.state, 'country', m.country,
      'role_id', m.role_id, 'role_name', coalesce((
        select string_agg(cr.name, ', ' order by cr.name)
        from public.church_member_roles mr
        join public.church_roles cr on cr.id = mr.role_id
        where mr.member_id = m.id
      ), r.name),
      'role_ids', coalesce((
        select jsonb_agg(mr.role_id)
        from public.church_member_roles mr
        where mr.member_id = m.id
      ), case when m.role_id is not null then jsonb_build_array(m.role_id) else '[]'::jsonb end),
      'branch_id', m.branch_id, 'branch_name', b.name, 'branch_region', b.region,
      'ministry', m.ministry,
      'registration_categories', to_jsonb(coalesce(m.registration_categories, '{}')),
      'audience_teams', to_jsonb(coalesce(m.audience_teams, '{}')),
      'worker_code', m.worker_code,
      'participant_code', m.participant_code,
      'worker_position', m.worker_position,
      'availability', m.availability,
      'meeting_sept_4', m.meeting_sept_4,
      'meeting_sept_5', m.meeting_sept_5,
      'absence_reason', m.absence_reason,
      'convention_group', m.convention_group,
      'age_range', m.age_range,
      'whatsapp', m.whatsapp,
      'attended_before', m.attended_before,
      'expectations', m.expectations,
      'medical_need', m.medical_need,
      'convention_submitted_at', m.convention_submitted_at,
      'baptism_status', m.baptism_status,
      'marital_status', m.marital_status, 'occupation', m.occupation,
      'emergency_contact_name', m.emergency_contact_name,
      'emergency_contact_phone', m.emergency_contact_phone,
      'notes', m.notes, 'form_data', m.form_data,
      'status', m.status, 'registered_by_admin', m.registered_by_admin,
      'email_sent', m.email_sent, 'created_at', m.created_at, 'updated_at', m.updated_at
    ) order by m.created_at desc)
    from public.church_members m
    left join public.church_roles r on r.id = m.role_id
    left join public.church_branches b on b.id = m.branch_id
    where (
      p_role_id is null
      or m.role_id = p_role_id
      or exists (
        select 1 from public.church_member_roles mr
        where mr.member_id = m.id and mr.role_id = p_role_id
      )
    )
      and (p_branch_id is null or m.branch_id = p_branch_id)
      and (
        p_status_group is null or p_status_group in ('', 'all')
        or (p_status_group = 'pending' and m.status = 'pending')
        or (p_status_group = 'approved' and m.status in ('approved', 'active'))
        or (p_status_group = 'inactive' and m.status = 'inactive')
      )
  ), '[]'::jsonb);
end;
$$;


-- Allow status-only member updates (e.g. Approve) without re-validating first name.
-- Name fields are only rewritten when the payload actually includes them.

create or replace function public.admin_update_church_member(p_token text, p_id uuid, p_data jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_row public.church_members%rowtype;
  v_ids uuid[];
  v_person record;
  v_has_name boolean;
begin
  perform public._require_permission(p_token, 'church_members', 'edit');

  v_has_name :=
    coalesce(nullif(trim(p_data->>'first_name'), ''), '') <> ''
    or coalesce(nullif(trim(p_data->>'last_name'), ''), '') <> ''
    or coalesce(nullif(trim(p_data->>'full_name'), ''), '') <> '';

  if v_has_name then
    select * into v_person from public._compose_person_name(
      coalesce(p_data->>'name_title', ''),
      coalesce(p_data->>'first_name', ''),
      coalesce(p_data->>'last_name', ''),
      coalesce(p_data->>'full_name', '')
    );
  end if;

  update public.church_members set
    name_title = case when v_has_name then v_person.name_title else name_title end,
    first_name = case when v_has_name then v_person.first_name else first_name end,
    last_name = case when v_has_name then v_person.last_name else last_name end,
    full_name = case when v_has_name then v_person.full_name else full_name end,
    email = coalesce(nullif(lower(trim(p_data->>'email')), ''), email),
    phone = coalesce(p_data->>'phone', phone),
    gender = coalesce(p_data->>'gender', gender),
    date_of_birth = case when p_data ? 'date_of_birth' then nullif(p_data->>'date_of_birth', '')::date else date_of_birth end,
    address = coalesce(p_data->>'address', address),
    city = coalesce(p_data->>'city', city),
    state = coalesce(p_data->>'state', state),
    country = coalesce(p_data->>'country', country),
    branch_id = coalesce(nullif(p_data->>'branch_id', '')::uuid, branch_id),
    ministry = coalesce(p_data->>'ministry', ministry),
    baptism_status = coalesce(p_data->>'baptism_status', baptism_status),
    marital_status = coalesce(p_data->>'marital_status', marital_status),
    occupation = coalesce(p_data->>'occupation', occupation),
    emergency_contact_name = coalesce(p_data->>'emergency_contact_name', emergency_contact_name),
    emergency_contact_phone = coalesce(p_data->>'emergency_contact_phone', emergency_contact_phone),
    notes = coalesce(p_data->>'notes', notes),
    form_data = coalesce(p_data->'form_data', form_data),

    registration_categories = case when p_data ? 'registration_categories' then public._json_text_array(p_data->'registration_categories') else registration_categories end,
    audience_teams = case when p_data ? 'audience_teams' then public._json_text_array(p_data->'audience_teams') else audience_teams end,
    worker_code = case when p_data ? 'worker_code' then coalesce(p_data->>'worker_code', '') else worker_code end,
    participant_code = case when p_data ? 'participant_code' then coalesce(p_data->>'participant_code', '') else participant_code end,
    worker_position = case when p_data ? 'worker_position' then coalesce(p_data->>'worker_position', '') else worker_position end,
    availability = case when p_data ? 'availability' then coalesce(p_data->>'availability', '') else availability end,
    meeting_sept_4 = case when p_data ? 'meeting_sept_4' then coalesce(p_data->>'meeting_sept_4', '') else meeting_sept_4 end,
    meeting_sept_5 = case when p_data ? 'meeting_sept_5' then coalesce(p_data->>'meeting_sept_5', '') else meeting_sept_5 end,
    absence_reason = case when p_data ? 'absence_reason' then coalesce(p_data->>'absence_reason', '') else absence_reason end,
    convention_group = case when p_data ? 'convention_group' then coalesce(p_data->>'convention_group', '') else convention_group end,
    age_range = case when p_data ? 'age_range' then coalesce(p_data->>'age_range', '') else age_range end,
    whatsapp = case when p_data ? 'whatsapp' then coalesce(p_data->>'whatsapp', '') else whatsapp end,
    attended_before = case when p_data ? 'attended_before' then coalesce(p_data->>'attended_before', '') else attended_before end,
    expectations = case when p_data ? 'expectations' then coalesce(p_data->>'expectations', '') else expectations end,
    medical_need = case when p_data ? 'medical_need' then coalesce(p_data->>'medical_need', '') else medical_need end,
    status = coalesce(nullif(p_data->>'status', ''), status),
    updated_at = now()
  where id = p_id returning * into v_row;
  if not found then raise exception 'Member not found'; end if;

  v_ids := public._parse_role_ids(p_data, v_row.role_id);
  if cardinality(v_ids) > 0 then
    perform public._set_member_roles(p_id, v_ids);
    select * into v_row from public.church_members where id = p_id;
  end if;
  return to_jsonb(v_row);
end;
$$;

create or replace function public._apply_change_request(p_req public.admin_change_requests)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  d jsonb := coalesce(p_req.payload, '{}'::jsonb);
  v_ids uuid[];
  v_person record;
  v_has_name boolean;
begin
  if p_req.action = 'delete' then
    if p_req.resource_type = 'church_members' then
      delete from public.church_members where id = p_req.resource_id;
    elsif p_req.resource_type = 'program_registrations' then
      delete from public.program_registrations where id = p_req.resource_id;
    elsif p_req.resource_type = 'volunteer_applications' then
      delete from public.volunteer_applications where id = p_req.resource_id;
    elsif p_req.resource_type = 'church_branches' then
      delete from public.church_branches where id = p_req.resource_id;
    elsif p_req.resource_type = 'church_roles' then
      delete from public.church_roles where id = p_req.resource_id;
    elsif p_req.resource_type = 'church_programs' then
      delete from public.church_programs where id = p_req.resource_id;
    elsif p_req.resource_type = 'announcements' then
      delete from public.announcements where id = p_req.resource_id;
    elsif p_req.resource_type = 'contact_messages' then
      delete from public.contact_messages where id = p_req.resource_id;
    else
      raise exception 'Unsupported delete type: %', p_req.resource_type;
    end if;
    return;
  end if;

  if p_req.action = 'update' and p_req.resource_type = 'church_members' then
    v_has_name :=
      coalesce(nullif(trim(d->>'first_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'last_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'full_name'), ''), '') <> '';

    if v_has_name then
      select * into v_person from public._compose_person_name(
        coalesce(d->>'name_title', ''), coalesce(d->>'first_name', ''),
        coalesce(d->>'last_name', ''), coalesce(d->>'full_name', '')
      );
    end if;

    update public.church_members set
      name_title = case when v_has_name then v_person.name_title else name_title end,
      first_name = case when v_has_name then v_person.first_name else first_name end,
      last_name = case when v_has_name then v_person.last_name else last_name end,
      full_name = case when v_has_name then v_person.full_name else full_name end,
      email = coalesce(nullif(lower(trim(d->>'email')), ''), email),
      phone = coalesce(d->>'phone', phone),
      gender = coalesce(d->>'gender', gender),
      date_of_birth = case when d ? 'date_of_birth' then nullif(d->>'date_of_birth', '')::date else date_of_birth end,
      address = coalesce(d->>'address', address),
      city = coalesce(d->>'city', city),
      state = coalesce(d->>'state', state),
      country = coalesce(d->>'country', country),
      branch_id = coalesce(nullif(d->>'branch_id', '')::uuid, branch_id),
      ministry = coalesce(d->>'ministry', ministry),
      baptism_status = coalesce(d->>'baptism_status', baptism_status),
      marital_status = coalesce(d->>'marital_status', marital_status),
      occupation = coalesce(d->>'occupation', occupation),
      emergency_contact_name = coalesce(d->>'emergency_contact_name', emergency_contact_name),
      emergency_contact_phone = coalesce(d->>'emergency_contact_phone', emergency_contact_phone),
      notes = coalesce(d->>'notes', notes),
      form_data = coalesce(d->'form_data', form_data),

    registration_categories = case when d ? 'registration_categories' then public._json_text_array(d->'registration_categories') else registration_categories end,
    audience_teams = case when d ? 'audience_teams' then public._json_text_array(d->'audience_teams') else audience_teams end,
    worker_code = case when d ? 'worker_code' then coalesce(d->>'worker_code', '') else worker_code end,
    participant_code = case when d ? 'participant_code' then coalesce(d->>'participant_code', '') else participant_code end,
    worker_position = case when d ? 'worker_position' then coalesce(d->>'worker_position', '') else worker_position end,
    availability = case when d ? 'availability' then coalesce(d->>'availability', '') else availability end,
    meeting_sept_4 = case when d ? 'meeting_sept_4' then coalesce(d->>'meeting_sept_4', '') else meeting_sept_4 end,
    meeting_sept_5 = case when d ? 'meeting_sept_5' then coalesce(d->>'meeting_sept_5', '') else meeting_sept_5 end,
    absence_reason = case when d ? 'absence_reason' then coalesce(d->>'absence_reason', '') else absence_reason end,
    convention_group = case when d ? 'convention_group' then coalesce(d->>'convention_group', '') else convention_group end,
    age_range = case when d ? 'age_range' then coalesce(d->>'age_range', '') else age_range end,
    whatsapp = case when d ? 'whatsapp' then coalesce(d->>'whatsapp', '') else whatsapp end,
    attended_before = case when d ? 'attended_before' then coalesce(d->>'attended_before', '') else attended_before end,
    expectations = case when d ? 'expectations' then coalesce(d->>'expectations', '') else expectations end,
    medical_need = case when d ? 'medical_need' then coalesce(d->>'medical_need', '') else medical_need end,
      status = coalesce(nullif(d->>'status', ''), status),
      updated_at = now()
    where id = p_req.resource_id;
    v_ids := public._parse_role_ids(d, null);
    if cardinality(v_ids) > 0 then
      perform public._set_member_roles(p_req.resource_id, v_ids);
    end if;
    return;
  end if;

  if p_req.action = 'update' and p_req.resource_type = 'program_registrations' then
    v_has_name :=
      coalesce(nullif(trim(d->>'first_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'last_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'full_name'), ''), '') <> '';

    if v_has_name then
      select * into v_person from public._compose_person_name(
        coalesce(d->>'name_title', ''), coalesce(d->>'first_name', ''),
        coalesce(d->>'last_name', ''), coalesce(d->>'full_name', '')
      );
      update public.program_registrations set
        name_title = v_person.name_title, first_name = v_person.first_name,
        last_name = v_person.last_name, full_name = v_person.full_name,
        email = coalesce(d->>'email', email),
        phone = coalesce(d->>'phone', phone),
        branch_id = coalesce(nullif(d->>'branch_id', '')::uuid, branch_id),
        status = coalesce(nullif(d->>'status', ''), status),
        form_data = coalesce(d->'form_data', form_data),
        updated_at = now()
      where id = p_req.resource_id;
    else
      update public.program_registrations set
        email = coalesce(d->>'email', email),
        phone = coalesce(d->>'phone', phone),
        branch_id = coalesce(nullif(d->>'branch_id', '')::uuid, branch_id),
        status = coalesce(nullif(d->>'status', ''), status),
        form_data = coalesce(d->'form_data', form_data),
        updated_at = now()
      where id = p_req.resource_id;
    end if;
    return;
  end if;

  if p_req.action = 'update' and p_req.resource_type = 'volunteer_applications' then
    v_has_name :=
      coalesce(nullif(trim(d->>'first_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'last_name'), ''), '') <> ''
      or coalesce(nullif(trim(d->>'full_name'), ''), '') <> '';

    if v_has_name then
      select * into v_person from public._compose_person_name(
        coalesce(d->>'name_title', ''), coalesce(d->>'first_name', ''),
        coalesce(d->>'last_name', ''), coalesce(d->>'full_name', '')
      );
      update public.volunteer_applications set
        name_title = v_person.name_title, first_name = v_person.first_name,
        last_name = v_person.last_name, full_name = v_person.full_name,
        email = coalesce(d->>'email', email),
        phone = coalesce(d->>'phone', phone),
        role_interest = coalesce(d->>'role_interest', role_interest),
        status = coalesce(nullif(d->>'status', ''), status),
        review_notes = coalesce(d->>'review_notes', review_notes),
        updated_at = now()
      where id = p_req.resource_id;
    else
      update public.volunteer_applications set
        email = coalesce(d->>'email', email),
        phone = coalesce(d->>'phone', phone),
        role_interest = coalesce(d->>'role_interest', role_interest),
        status = coalesce(nullif(d->>'status', ''), status),
        review_notes = coalesce(d->>'review_notes', review_notes),
        updated_at = now()
      where id = p_req.resource_id;
    end if;
    return;
  end if;
end;
$$;


