-- Add convention teams to the saved ministry dropdown when an admin catalog already exists.
do $dropdowns$
declare
  v_value jsonb;
  v_catalogs jsonb;
  v_item jsonb;
  v_opts jsonb;
  v_new text[] := array[
    'Choir', 'Ushers', 'Prayer Team', 'Media / Photography', 'Medical Team', 'Technical / Engineers',
    'Welfare / Hospitality', 'Protocol', 'Feeding', 'Interpretation', 'Decoration', 'Registration',
    'Moderators', 'Accommodation', 'Logistics', 'Transportation', 'Sanitation', 'Publicity'
  ];
  v_opt text;
  i int;
begin
  select value into v_value from public.site_settings where key = 'site';
  if v_value is null or jsonb_typeof(v_value -> 'formDropdowns') is distinct from 'array' then
    return;
  end if;
  v_catalogs := v_value -> 'formDropdowns';
  if coalesce(jsonb_array_length(v_catalogs), 0) = 0 then
    return;
  end if;
  for i in 0 .. jsonb_array_length(v_catalogs) - 1 loop
    v_item := v_catalogs -> i;
    if coalesce(v_item->>'id', '') = 'ministry' or coalesce(v_item->>'fieldKey', '') = 'ministry' then
      v_opts := coalesce(v_item->'options', '[]'::jsonb);
      foreach v_opt in array v_new loop
        if not (v_opts @> jsonb_build_array(v_opt)) then
          v_opts := v_opts || jsonb_build_array(v_opt);
        end if;
      end loop;
      v_item := jsonb_set(v_item, '{options}', v_opts, true);
      v_catalogs := jsonb_set(v_catalogs, array[i::text], v_item, true);
    end if;
  end loop;
  update public.site_settings
  set value = jsonb_set(v_value, '{formDropdowns}', v_catalogs, true),
      updated_at = now()
  where key = 'site';
end
$dropdowns$;

