ed": "n Theme Implies, I hope to bNo"}, {"full_name": "Atanda John", "gender": "Male", "date_of_birth": "", "phone": "07034747171", "whatsapp": "07034747171", "email": "thtr@gmail.com", "state": "", "occupation": "", "emergency_contact_name": "Mom", "emergency_contact_phone": "07034747171", "branch": "Headquarter", "categories": ["participant"], "teams": [], "worker_code": "", "participant_code": "PT-OTAO1346", "worker_position": "", "availability": "", "meeting_sept_4": "", "meeting_sept_5": "", "absence_reason": "", "convention_group": "THE RESTORERS", "submitted_at": "2026-09-12T12:54:11.346Z", "age_range": "13\u201317", "attended_before": "First time", "expectations": "Blessing", "medical_need": "No"}]$conv$;
  v_rec jsonb;
  v_id uuid;
  v_name text;
  v_name_key text;
  v_phone text;
  v_phone_key text;
  v_email text;
  v_worker_code text;
  v_participant_code text;
  v_branch text;
  v_branch_id uuid;
  v_cats text[];
  v_teams text[];
  v_dob date;
  v_submitted timestamptz;
  v_worker_role uuid;
  v_member_role uuid;
  v_role_ids uuid[];
  v_note text;
  v_count int;
begin
  select id into v_worker_role from public.church_roles where name = 'Worker' and is_active = true order by sort_order limit 1;
  select id into v_member_role from public.church_roles where name = 'Member' and is_active = true order by sort_order limit 1;

  for v_rec in select value from jsonb_array_elements(v_rows) loop
    v_name := trim(coalesce(v_rec->>'full_name', ''));
    if v_name = '' then
      continue;
    end if;
    v_name_key := regexp_replace(lower(v_name), '[^a-z]', '', 'g');
    v_phone := trim(coalesce(v_rec->>'phone', ''));
    v_phone_key := right(regexp_replace(v_phone, '\D', '', 'g'), 10);
    if length(regexp_replace(v_phone, '\D', '', 'g')) < 10 then
      v_phone_key := '';
    end if;
    v_email := lower(trim(coalesce(v_rec->>'email', '')));
    v_worker_code := trim(coalesce(v_rec->>'worker_code', ''));
    v_participant_code := trim(coalesce(v_rec->>'participant_code', ''));
    v_branch := trim(coalesce(v_rec->>'branch', ''));
    v_cats := public._json_text_array(v_rec->'categories');
    v_teams := public._json_text_array(v_rec->'teams');
    v_branch_id := null;
    if v_branch <> '' then
      select id into v_branch_id
      from public.church_branches
      where lower(name) = lower(v_branch) and is_active = true
      limit 1;
    end if;
    if coalesce(v_rec->>'date_of_birth', '') ~ '^\d{4}-\d{2}-\d{2}$' then
      v_dob := (v_rec->>'date_of_birth')::date;
    else
      v_dob := null;
    end if;
    if coalesce(v_rec->>'submitted_at', '') ~ '^\d{4}-\d{2}-\d{2}T' then
      v_submitted := (v_rec->>'submitted_at')::timestamptz;
    else
      v_submitted := null;
    end if;
    v_note := 'Youth convention registration'
      || case when v_worker_code <> '' then ' ' || v_worker_code else '' end
      || case when v_participant_code <> '' then ' ' || v_participant_code else '' end;

    v_id := null;
    if v_worker_code <> '' then
      select id into v_id from public.church_members where worker_code = v_worker_code limit 1;
    end if;
    if v_id is null and v_participant_code <> '' then
      select id into v_id from public.church_members where participant_code = v_participant_code limit 1;
    end if;
    if v_id is null and v_phone_key <> '' then
      select m.id into v_id
      from public.church_members m
      where right(regexp_replace(coalesce(m.phone, ''), '\D', '', 'g'), 10) = v_phone_key
        and length(regexp_replace(coalesce(m.phone, ''), '\D', '', 'g')) >= 10
        and (
          regexp_replace(lower(m.full_name), '[^a-z]', '', 'g') = v_name_key
          or (
            length(v_name_key) >= 8
            and length(regexp_replace(lower(m.full_name), '[^a-z]', '', 'g')) >= 8
            and (
              position(v_name_key in regexp_replace(lower(m.full_name), '[^a-z]', '', 'g')) > 0
              or position(regexp_replace(lower(m.full_name), '[^a-z]', '', 'g') in v_name_key) > 0
            )
          )
        )
      order by m.created_at
      limit 1;
    end if;
    if v_id is null and v_name_key <> '' then
      select count(*) into v_count
      from public.church_members m
      where regexp_replace(lower(m.full_name), '[^a-z]', '', 'g') = v_name_key;
      if v_count = 1 then
        select id into v_id
        from public.church_members m
        where regexp_replace(lower(m.full_name), '[^a-z]', '', 'g') = v_name_key
        limit 1;
      end if;
    end if;

    if v_id is null then
      insert into public.church_members (
        full_name, email, phone, gender, date_of_birth, state, country,
        ministry, occupation, emergency_contact_name, emergency_contact_phone,
        notes, branch_id, registered_by_admin, status, created_at,
        registration_categories, audience_teams, worker_code, participant_code,
        worker_position, availability, meeting_sept_4, meeting_sept_5, absence_reason,
        convention_group, age_range, whatsapp, attended_before, expectations, medical_need,
        convention_submitted_at
      ) values (
        v_name,
        v_email,
        v_phone,
        coalesce(v_rec->>'gender', ''),
        v_dob,
        coalesce(v_rec->>'state', ''),
        'Nigeria',
        array_to_string(v_teams, ', '),
        coalesce(v_rec->>'occupation', ''),
        coalesce(v_rec->>'emergency_contact_name', ''),
        coalesce(v_rec->>'emergency_contact_phone', ''),
        v_note,
        v_branch_id,
        true,
        'approved',
        coalesce(v_submitted, now()),
        v_cats,
        v_teams,
        v_worker_code,
        v_participant_code,
        coalesce(v_rec->>'worker_position', ''),
        coalesce(v_rec->>'availability', ''),
        coalesce(v_rec->>'meeting_sept_4', ''),
        coalesce(v_rec->>'meeting_sept_5', ''),
        coalesce(v_rec->>'absence_reason', ''),
        coalesce(v_rec->>'convention_group', ''),
        coalesce(v_rec->>'age_range', ''),
        coalesce(v_rec->>'whatsapp', ''),
        coalesce(v_rec->>'attended_before', ''),
        coalesce(v_rec->>'expectations', ''),
        coalesce(v_rec->>'medical_need', ''),
        v_submitted
      ) returning id into v_id;

      v_role_ids := '{}';
      if 'worker' = any(v_cats) and v_worker_role is not null then
        v_role_ids := v_role_ids || v_worker_role;
      end if;
      if 'participant' = any(v_cats) and v_member_role is not null then
        v_role_ids := v_role_ids || v_member_role;
      end if;
      if cardinality(v_role_ids) = 0 and v_member_role is not null then
        v_role_ids := array[v_member_role];
      end if;
      if cardinality(v_role_ids) > 0 then
        perform public._set_member_roles(v_id, v_role_ids);
      end if;
    else
      update public.church_members set
        registration_categories = (
          select coalesce(array_agg(distinct cat), '{}'::text[])
          from (
            select unnest(coalesce(registration_categories, '{}') || v_cats) as cat
          ) s
          where cat <> ''
        ),
        audience_teams = (
          select coalesce(array_agg(distinct team), '{}'::text[])
          from (
            select unnest(coalesce(audience_teams, '{}') || v_teams) as team
          ) s
          where team <> ''
        ),
        ministry = (
          select coalesce(string_agg(team, ', ' order by team), ministry)
          from (
            select distinct trim(part) as team
            from (
              select unnest(string_to_array(coalesce(ministry, ''), ',')) as part
              union
              select unnest(v_teams)
            ) parts
            where trim(part) <> ''
          ) named
        ),
        email = case when coalesce(email, '') = '' and v_email <> '' then v_email else email end,
        phone = case when coalesce(phone, '') = '' and v_phone <> '' then v_phone else phone end,
        gender = case when coalesce(gender, '') = '' then coalesce(nullif(v_rec->>'gender', ''), gender) else gender end,
        date_of_birth = coalesce(date_of_birth, v_dob),
        state = case when coalesce(state, '') = '' then coalesce(nullif(v_rec->>'state', ''), state) else state end,
        occupation = case when coalesce(occupation, '') = '' then coalesce(nullif(v_rec->>'occupation', ''), occupation) else occupation end,
        emergency_contact_name = case when coalesce(emergency_contact_name, '') = '' then coalesce(nullif(v_rec->>'emergency_contact_name', ''), emergency_contact_name) else emergency_contact_name end,
        emergency_contact_phone = case when coalesce(emergency_contact_phone, '') = '' then coalesce(nullif(v_rec->>'emergency_contact_phone', ''), emergency_contact_phone) else emergency_contact_phone end,
        branch_id = coalesce(branch_id, v_branch_id),
        worker_code = case when coalesce(worker_code, '') = '' then v_worker_code else worker_code end,
        participant_code = case when coalesce(participant_code, '') = '' then v_participant_code else participant_code end,
        worker_position = case when coalesce(worker_position, '') = '' then coalesce(v_rec->>'worker_position', '') else worker_position end,
        availability = case when coalesce(availability, '') = '' then coalesce(v_rec->>'availability', '') else availability end,
        meeting_sept_4 = case when coalesce(meeting_sept_4, '') = '' then coalesce(v_rec->>'meeting_sept_4', '') else meeting_sept_4 end,
        meeting_sept_5 = case when coalesce(meeting_sept_5, '') = '' then coalesce(v_rec->>'meeting_sept_5', '') else meeting_sept_5 end,
        absence_reason = case when coalesce(absence_reason, '') = '' then coalesce(v_rec->>'absence_reason', '') else absence_reason end,
        convention_group = case when coalesce(convention_group, '') = '' then coalesce(v_rec->>'convention_group', '') else convention_group end,
        age_range = case when coalesce(age_range, '') = '' then coalesce(v_rec->>'age_range', '') else age_range end,
        whatsapp = case when coalesce(whatsapp, '') = '' then coalesce(v_rec->>'whatsapp', '') else whatsapp end,
        attended_before = case when coalesce(attended_before, '') = '' then coalesce(v_rec->>'attended_before', '') else attended_before end,
        expectations = case when coalesce(expectations, '') = '' then coalesce(v_rec->>'expectations', '') else expectations end,
        medical_need = case when coalesce(medical_need, '') = '' then coalesce(v_rec->>'medical_need', '') else medical_need end,
        convention_submitted_at = coalesce(convention_submitted_at, v_submitted),
        notes = case
          when notes ilike '%Youth convention registration%' then notes
          else trim(both E'\n' from coalesce(notes, '') || E'\n' || v_note)
        end,
        updated_at = now()
      where id = v_id;
    end if;
  end loop;
end
$import$;
